"""Windowed SIRS-criteria screening engine over streaming vitals.

Criteria (score 1 each, STRICT inequalities):
    temp_c      > 38.0  or < 36.0
    heart_rate  > 90
    resp_rate   > 20
    wbc         > 12.0  or < 4.0

An alert fires for a patient when >= 2 criteria are met SIMULTANEOUSLY,
using each vital's most recent value within a 60-minute lookback from the
evaluation instant; a vital older than 60 minutes is unknown and
contributes 0.

Events arrive as (patient, ts, kind, value), possibly out of order within
a 10-minute skew.  To make alerts independent of arrival order, every
ingestion deterministically replays the patient's full event history in
timestamp order and re-derives the alert episodes:

  * an alert fires exactly once per episode (first instant where >= 2
    criteria hold while not already in an episode);
  * a new episode may start (re-alert) only after the patient was below
    2 criteria continuously for 30+ minutes;
  * a drop below 2 criteria lasting < 30 minutes does NOT end the episode
    (no duplicate alert when criteria rise again).

Pure stdlib.
"""

from __future__ import annotations

VITALS = ("temp_c", "heart_rate", "resp_rate", "wbc")

LOOKBACK_MIN = 60.0     # vital older than this is unknown at evaluation
RECOVERY_MIN = 30.0     # below-2-criteria duration required to close an episode
ALERT_THRESHOLD = 2     # criteria needed simultaneously to be in an episode


def _to_minutes(ts) -> float:
    """Accept numeric minutes or datetime; normalise to float."""
    if hasattr(ts, "timestamp"):  # datetime-like
        return ts.timestamp() / 60.0
    return float(ts)


class SIRSEngine:
    def __init__(self,
                 lookback_min: float = LOOKBACK_MIN,
                 recovery_min: float = RECOVERY_MIN,
                 threshold: int = ALERT_THRESHOLD):
        self.lookback_min = float(lookback_min)
        self.recovery_min = float(recovery_min)
        self.threshold = int(threshold)
        # patient -> list[(ts_min, kind, value)] in arrival order (unsorted)
        self._events: dict[str, list[tuple[float, str, float]]] = {}
        # patient -> sorted list of alert instants (minutes), one per episode
        self._alerts: dict[str, list[float]] = {}

    # ------------------------------------------------------------------ #
    # ingestion
    # ------------------------------------------------------------------ #
    def ingest(self, patient: str, ts, kind: str, value: float) -> bool:
        """Record one event and re-evaluate the whole timeline.

        Returns True iff this ingestion produced a *new* alert episode
        firing (at any point on the timeline).  Because replay is fully
        deterministic on (ts, kind, value) tuples, out-of-order arrival
        within the skew yields identical alerts to sorted arrival.
        """
        t = _to_minutes(ts)
        self._events.setdefault(patient, []).append((t, kind, float(value)))

        before = len(self._alerts.get(patient, []))
        self._alerts[patient] = self._replay(patient)
        return len(self._alerts[patient]) > before

    # ------------------------------------------------------------------ #
    # queries
    # ------------------------------------------------------------------ #
    def evaluate_at(self, patient: str, ts) -> dict:
        """Evaluate SIRS state for `patient` at instant `ts`.

        Returns {"criteria": {kind: bool}, "score": int, "values": {...}}.
        Unknown/stale vitals have criterion False and value None.
        """
        t = _to_minutes(ts)
        events = self._events.get(patient, [])
        criteria: dict[str, bool] = {}
        values: dict[str, float | None] = {}

        for kind in VITALS:
            latest = None
            for et, ekind, evalue in events:
                if ekind != kind or et > t:
                    continue  # future events are invisible at t
                if t - et > self.lookback_min:
                    continue  # stale
                if latest is None or et > latest[0]:
                    latest = (et, evalue)

            if latest is None:
                values[kind] = None
                criteria[kind] = False
            else:
                values[kind] = latest[1]
                criteria[kind] = _meets(kind, latest[1])

        score = sum(criteria.values())
        return {"criteria": criteria, "score": score, "values": values}

    def alerts(self, patient: str) -> list[float]:
        """Alert instants (one per episode), ascending."""
        return list(self._alerts.get(patient, []))

    def in_episode(self, patient: str, ts=None) -> bool:
        """Is the patient inside an alert episode now (or at `ts`)?"""
        fired = self.alerts(patient)
        if not fired:
            return False
        if ts is None:
            return self.evaluate_at(patient, self._last_event_ts(patient))["score"] >= self.threshold
        return self.evaluate_at(patient, ts)["score"] >= self.threshold

    # ------------------------------------------------------------------ #
    # internals
    # ------------------------------------------------------------------ #
    def _eval_instants(self, patient: str) -> list[float]:
        """Deduplicated, sorted evaluation instants = all event timestamps."""
        return sorted({t for t, _, _ in self._events.get(patient, [])})

    def _last_event_ts(self, patient: str) -> float:
        return max(t for t, _, _ in self._events.get(patient, []))

    def _replay(self, patient: str) -> list[float]:
        """Deterministically derive one alert per episode over full history."""
        alerts: list[float] = []
        in_episode = False
        below_since: float | None = None  # first instant of continuous below-threshold run

        for t in self._eval_instants(patient):
            score = self.evaluate_at(patient, t)["score"]
            if score >= self.threshold:
                if not in_episode:
                    # New episode only after a genuine recovery gap, or at start.
                    recovered = below_since is not None and (t - below_since) >= self.recovery_min
                    if not alerts or recovered or below_since is None:
                        alerts.append(t)
                        in_episode = True
                    else:
                        # Was below <30min then back up: still same episode.
                        pass
                    below_since = None
                else:
                    below_since = None
            else:
                if in_episode and below_since is None:
                    below_since = t
                if in_episode and below_since is not None and (t - below_since) >= self.recovery_min:
                    in_episode = False  # episode closed by sustained recovery

        return alerts


def _meets(kind: str, value: float) -> bool:
    """Strict SIRS inequalities — boundary values never trigger."""
    if kind == "temp_c":
        return value > 38.0 or value < 36.0
    if kind == "heart_rate":
        return value > 90
    if kind == "resp_rate":
        return value > 20
    if kind == "wbc":
        return value > 12.0 or value < 4.0
    raise ValueError(f"unknown vital kind: {kind!r}")

